'use strict';
(() => {
 const bridge=window.BlockoutBridge;if(!bridge)return;
 const button=document.createElement('button');button.id='cloudButton';button.className='quiet cloud-header-button';button.title='AI haritaları ve MCP bağlantısı';button.innerHTML=bridge.icon('cube')+'<span>AI Haritaları</span>';
 document.querySelector('.header-actions').prepend(button);
 const dialog=document.querySelector('#cloudDialog'),status=document.querySelector('#cloudStatus'),list=document.querySelector('#cloudProjects'),urlInput=document.querySelector('#mcpUrl');
 urlInput.value=location.protocol==='file:'?'Yerel sunucuyu başlat':location.origin+'/mcp';
 let remote=null,dirty=false,saving=false,applying=false,conflict=false,saveTimeout=null,online=false,requestEpoch=0,editSerial=0,publishing=false;
 const escape=bridge.escape;
 function setStatus(message,isError=false){status.textContent=message;status.classList.toggle('error',isError);button.classList.toggle('cloud-linked',!!remote);button.title=remote?`${remote.name} · Bulut kaydı ${remote.revision}${dirty?' · Yerel değişiklik var':''}`:'AI haritaları ve MCP bağlantısı';}
 async function api(path,options={}){const response=await fetch(path,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await response.json();}catch{throw Object.assign(new Error('Bu sürümde bulut bağlantısı kullanılamıyor. Yerel sunucuyu başlat veya yayımlanan sürümü aç.'),{status:response.status});}if(!response.ok)throw Object.assign(new Error(data.error||'Bağlantı kurulamadı.'),{status:response.status});return data;}
 function errorMessage(error){return error.status===401?'Haritalarına erişmek için Blockout hesabınla oturum aç.':error.message;}
 async function refresh(){try{const data=await api('/api/projects');online=true;setStatus(remote?`${remote.name} · ${conflict?'Çakışma var; yerel çizimin korunuyor':dirty?'Kaydedilmeyi bekliyor':'Bağlı, otomatik eşitleme açık'}`:'MCP hazır. Modelin oluşturduğu haritalar burada görünür.',conflict);list.innerHTML=data.projects.length?data.projects.map(p=>`<button class="cloud-project" data-cloud-id="${escape(p.id)}"><span><strong>${escape(p.name)}</strong><small>Sürüm ${p.revision} · ${new Date(p.updated_at).toLocaleString('tr-TR')}</small></span><span>Aç</span></button>`).join(''):'<p class="cloud-empty">Henüz bulut haritası yok. Mevcut çizimini kaydet veya bağlı modelden bir harita oluşturmasını iste.</p>';return data.projects;}catch(error){online=false;setStatus(errorMessage(error),true);list.innerHTML='<p class="cloud-empty">Yerel çizimin çalışmaya devam eder. JSON indirerek yedekleyebilirsin.</p>';return [];}}
 function localBackup(){try{localStorage.setItem('blockout.before-cloud.v1',JSON.stringify(bridge.snapshot()));}catch{}}
 async function loadCloud(id){const epoch=++requestEpoch;try{if(dirty){await sync();if(dirty){bridge.notify('Kaydedilmemiş yerel değişiklikler var. Önce JSON yedekle veya yeni bulut kopyası oluştur.');return;}}const serial=editSerial;const data=await api('/api/projects/'+encodeURIComponent(id));if(epoch!==requestEpoch||serial!==editSerial||bridge.busy()){bridge.notify('Harita yüklenirken yerel çizim değişti; çizimin korundu. Tekrar açabilirsin.');return;}localBackup();applying=true;try{bridge.load(data.project,false);}finally{applying=false;}remote={id:data.id,revision:data.revision,name:data.project.name};dirty=false;conflict=false;editSerial++;const url=new URL(location.href);url.searchParams.set('project',id);window.history.replaceState(null,'',url);dialog.close();setStatus(remote.name+' · Bağlı, otomatik eşitleme açık');bridge.notify('Bulut haritası açıldı. MCP değişiklikleri otomatik yansır.');}catch(error){setStatus(errorMessage(error),true);bridge.notify(errorMessage(error));}}
 async function sync(){if(!remote||!dirty||saving||conflict||publishing)return;if(bridge.busy()){scheduleSave();return;}saving=true;const epoch=requestEpoch,id=remote.id,revision=remote.revision,serial=editSerial,snapshot=bridge.snapshot();setStatus('Buluta kaydediliyor…');try{const data=await api('/api/projects/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({project:snapshot,expected_revision:revision})});if(epoch!==requestEpoch||remote?.id!==id)return;remote.revision=data.revision;remote.name=snapshot.name;if(serial===editSerial)dirty=false;setStatus(remote.name+' · '+(dirty?'Yeni değişiklikler kaydediliyor':'Bulut kaydı tamamlandı'));}catch(error){if(epoch!==requestEpoch)return;if(error.status===409){conflict=true;setStatus('Model ve editör aynı anda değişti. Yerel çizimin korundu; yeni bir bulut kopyası kaydet veya JSON yedekle.',true);bridge.notify('Eşitleme çakışması: yerel çizimin korundu. AI Haritaları bölümünü aç.');}else setStatus(errorMessage(error)+' Yerel çizimin korunuyor.',true);}finally{saving=false;if(dirty&&!conflict)scheduleSave();}}
 function scheduleSave(){clearTimeout(saveTimeout);saveTimeout=setTimeout(sync,900);}
 async function publish(){if(publishing||saving){bridge.notify('Devam eden kayıt işleminin bitmesini bekle.');return;}publishing=true;const epoch=requestEpoch,serial=editSerial,snapshot=bridge.snapshot();document.querySelector('#saveCloud').disabled=true;setStatus('Yeni bulut haritası oluşturuluyor…');try{const data=await api('/api/projects',{method:'POST',body:JSON.stringify({project:snapshot})});if(epoch!==requestEpoch)return;remote={id:data.id,revision:data.revision,name:snapshot.name};dirty=serial!==editSerial;conflict=false;const url=new URL(location.href);url.searchParams.set('project',remote.id);window.history.replaceState(null,'',url);bridge.notify('Bulut haritası kaydedildi. Model bu projeyi MCP üzerinden düzenleyebilir.');await refresh();}catch(error){setStatus(errorMessage(error),true);}finally{publishing=false;document.querySelector('#saveCloud').disabled=false;if(dirty&&!conflict)scheduleSave();}}
 function detach(){requestEpoch++;editSerial++;remote=null;dirty=false;conflict=false;clearTimeout(saveTimeout);const url=new URL(location.href);url.searchParams.delete('project');if(location.protocol!=='file:')window.history.replaceState(null,'',url);setStatus('Yerel çizim · MCP için buluta kaydet.');}
 button.addEventListener('click',()=>{dialog.showModal();refresh();});document.querySelector('#refreshCloud').addEventListener('click',refresh);document.querySelector('#saveCloud').addEventListener('click',publish);
 list.addEventListener('click',e=>{const item=e.target.closest('[data-cloud-id]');if(item)loadCloud(item.dataset.cloudId);});
 document.querySelector('#copyMcpUrl').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(urlInput.value);bridge.notify('MCP sunucu adresi kopyalandı.');}catch{urlInput.focus();urlInput.select();bridge.notify('Adresi seçtim; Ctrl+C ile kopyalayabilirsin.');}});
 window.addEventListener('blockout:change',()=>{if(applying)return;editSerial++;if(remote){dirty=true;scheduleSave();}});window.addEventListener('blockout:detach',detach);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)sync();});
 async function poll(){if(!remote||saving||dirty||conflict||publishing||document.hidden||bridge.busy())return;const epoch=requestEpoch,serial=editSerial,id=remote.id;try{const data=await api('/api/projects/'+encodeURIComponent(id));if(epoch!==requestEpoch||serial!==editSerial||dirty||saving||bridge.busy()||remote?.id!==id)return;if(data.revision!==remote.revision){applying=true;try{bridge.load(data.project,true);}finally{applying=false;}remote.revision=data.revision;remote.name=data.project.name;setStatus(remote.name+' · MCP değişiklikleri alındı');bridge.notify('Harita modelin değişiklikleriyle güncellendi.');}}catch(error){setStatus(errorMessage(error)+' Yerel çizimin korunuyor.',true);}}
 setInterval(poll,4000);const initialId=new URL(location.href).searchParams.get('project');if(initialId&&/^[\w-]{1,100}$/.test(initialId))loadCloud(initialId);
 window.BlockoutCloud={detach,refresh,sync,state:()=>({remote:remote?{...remote}:null,dirty,saving,conflict,online})};
})();
